/**
 * Bundles google-sheets/backend/*.gs into one paste-ready file.
 *
 *   node google-sheets/build-bundle.mjs
 *
 * Output: google-sheets/LUMINA-APPS-SCRIPT.gs
 *
 * The Apps Script editor accepts many .gs files, which is the nicer way to work
 * (clasp or manual paste). This bundle exists for the "one file, one paste"
 * route — the appsscript.json manifest still has to be set separately.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const backend = path.join(here, 'backend')

/** Load order matters only for readability — Apps Script hoists declarations. */
const ORDER = [
  'Config.gs',
  'Validation.gs',
  'SheetDb.gs',
  'AuthService.gs',
  'MembersService.gs',
  'SettingsService.gs',
  'BooksService.gs',
  'LoansService.gs',
  'ReservationsService.gs',
  'WishlistService.gs',
  'ReportsService.gs',
  'Setup.gs',
  'Code.gs',
]

const missing = ORDER.filter((file) => !fs.existsSync(path.join(backend, file)))
if (missing.length) {
  console.error(`Missing backend files: ${missing.join(', ')}`)
  process.exit(1)
}

const banner = `/**
 * ============================================================================
 *  LUMINA LIBRARY — Google Apps Script backend (single-file bundle)
 *
 *  Generated by google-sheets/build-bundle.mjs — do not edit this file.
 *  Edit the sources in google-sheets/backend/ and re-run the script.
 *
 *  HOW TO USE
 *   1. Open your spreadsheet → Extensions ▸ Apps Script.
 *   2. Delete the default Code.gs content and paste this whole file into it.
 *   3. Project Settings ▸ "Show appsscript.json" and paste backend/appsscript.json.
 *   4. Project Settings ▸ Script properties: set SPREADSHEET_ID, SEED_ADMIN_EMAIL,
 *      and optionally EMAIL_DOMAIN and API_BASE_URL.
 *   5. Run setupLumina(), then verifyLuminaSetup().
 *   6. Deploy ▸ New deployment ▸ Web app (Execute as: Me, Access: Anyone) and
 *      copy the /exec URL into VITE_API_BASE_URL.
 *  Full instructions: SETUP-GOOGLE-SHEETS.md
 * ============================================================================
 */
`

const parts = ORDER.map((file) => {
  const source = fs.readFileSync(path.join(backend, file), 'utf8').trimEnd()
  return `\n/* ===================== ${file} ===================== */\n\n${source}\n`
})

const target = path.join(here, 'LUMINA-APPS-SCRIPT.gs')
fs.writeFileSync(target, banner + parts.join(''), 'utf8')
const lines = fs.readFileSync(target, 'utf8').split('\n').length
console.log(`Wrote ${path.relative(process.cwd(), target)} (${ORDER.length} files, ${lines} lines)`)
